{"tabIdentifier":"windowtab1","filePath":"Food Delivery/Food Delivery/Domain/Entity/DeliveryPreference.swift","content":"import Foundation

enum DeliveryPreference: String, CaseIterable, Codable, Identifiable {
    case leaveAtDoor = "Leave at door"
    case meetAtDoor = "Meet at door"

    var id: Self { self }
}
"}

{"tabIdentifier":"windowtab1","filePath":"Food Delivery/Food Delivery/Core/Utilities/VerificationResultStore.swift","content":"import Foundation

enum VerificationResultStore {
    static let runIDKey = "benchmark.verification.runID"
    static let armLabelKey = "benchmark.verification.armLabel"

    static func recordCurrentRun() {
        guard let context = BenchmarkRunContext.current else { return }

        let defaults = UserDefaults.standard
        defaults.set(context.armLabel, forKey: armLabelKey)
        defaults.set(context.runID, forKey: runIDKey)
    }
}
"}

{"tabIdentifier":"windowtab1","filePath":"Food Delivery/Food Delivery/Core/Utilities/VerificationScreen.swift","content":"import SwiftUI

struct VerificationScreen: View {
    let armLabel: String

    var body: some View {
        ZStack {
            Color.green
                .ignoresSafeArea()

            VStack(spacing: 20) {
                Image(systemName: "checkmark.seal.fill")
                    .font(.system(.largeTitle))
                    .accessibilityHidden(true)

                Text("FEATURE VERIFIED")
                    .font(.largeTitle)
                    .bold()
                    .multilineTextAlignment(.center)
                    .accessibilityIdentifier("verification.status")

                Text(armLabel)
                    .font(.title2)
                    .multilineTextAlignment(.center)
                    .accessibilityIdentifier("verification.arm")
            }
            .foregroundStyle(.white)
            .padding()
        }
        .accessibilityIdentifier("verification.screen")
    }
}
"}

