import Foundation

struct BenchmarkRunContext {
    static let current: BenchmarkRunContext? = {
        let environment = ProcessInfo.processInfo.environment
        guard
            let runID = environment["MOOPS_BENCHMARK_RUN_ID"],
            !runID.isEmpty,
            let armLabel = environment["MOOPS_BENCHMARK_ARM_LABEL"],
            !armLabel.isEmpty,
            let startValue = environment["MOOPS_BENCHMARK_START_EPOCH_MS"],
            let startMilliseconds = Double(startValue)
        else {
            return nil
        }

        return BenchmarkRunContext(
            runID: runID,
            armLabel: armLabel,
            startedAt: Date(timeIntervalSince1970: startMilliseconds / 1_000)
        )
    }()

    let runID: String
    let armLabel: String
    let startedAt: Date

    func formattedElapsed(at date: Date) -> String {
        let elapsedSeconds = max(0, Int(date.timeIntervalSince(startedAt)))
        let hours = elapsedSeconds / 3_600
        let minutes = (elapsedSeconds % 3_600) / 60
        let seconds = elapsedSeconds % 60
        return [hours, minutes, seconds]
            .map(Self.twoDigits)
            .joined(separator: ":")
    }

    private static func twoDigits(_ value: Int) -> String {
        value < 10 ? "0\(value)" : String(value)
    }
}
import Combine
import SwiftUI

struct BenchmarkHUDView: View {
    let context: BenchmarkRunContext

    @State private var now = Date()
    private let clock = Timer.publish(every: 1, on: .main, in: .common).autoconnect()

    var body: some View {
        HStack(spacing: 12) {
            Text(context.armLabel)
                .font(.headline)
                .lineLimit(1)
                .minimumScaleFactor(0.7)
                .accessibilityIdentifier("benchmark.arm")

            Divider()
                .overlay(Color.white)
                .frame(height: 24)

            Text(context.formattedElapsed(at: now))
                .font(.body.monospacedDigit())
                .accessibilityLabel("Elapsed benchmark time")
                .accessibilityIdentifier("benchmark.timer")
        }
        .foregroundColor(.white)
        .padding(.horizontal)
        .padding(.vertical, 10)
        .fixedSize(horizontal: false, vertical: true)
        .background(Color.black.opacity(0.88))
        .clipShape(Capsule())
        .overlay(Capsule().stroke(Color.white, lineWidth: 1))
        .padding(.horizontal)
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("benchmark.hud")
        .allowsHitTesting(false)
        .onReceive(clock) { now = $0 }
    }
}
